package com.socialhub.facebookgroup.entity;

import jakarta.persistence.*; import lombok.*; import java.util.*; import java.time.*; import com.socialhub.user.entity.User; import com.socialhub.workspace.entity.Workspace; import com.socialhub.workspacemember.entity.WorkspaceMemberId; import com.socialhub.post.entity.Post; import com.socialhub.socialaccount.entity.SocialAccount; import com.socialhub.publishingjob.entity.PublishingJob; import com.socialhub.facebookgroup.entity.FacebookGroup;
@Entity @Table(name="facebook_groups") @Getter @Setter @NoArgsConstructor public class FacebookGroup { @Id @GeneratedValue(strategy=GenerationType.UUID) public UUID id; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="workspace_id",nullable=false) public Workspace workspace; @Column(name="external_group_id",nullable=false) public String externalGroupId; @Column(nullable=false) public String name; @Column(name="group_url",nullable=false,columnDefinition="TEXT") public String groupUrl; @Column(name="created_at",insertable=false,updatable=false) public OffsetDateTime createdAt; }
